arguments.new:
"""Batch an iterable into lazily produced lists."""


def batched(iterable, n):
    if n < 1:
        raise ValueError("n must be at least one")

    def batches():
        iterator = iter(iterable)
        while True:
            batch = []
            for _ in range(n):
                try:
                    batch.append(next(iterator))
                except StopIteration:
                    if batch:
                        yield batch
                    return
            yield batch

    return batches()

